     1→// apps/desktop/src/navigation/breadcrumb-builder.ts
     2→import { registry, humanize } from "./route-registry";
     3→import type { RouteEntry } from "./route-compiler";
     4→import type { IconData } from "@/components/ui/icon-picker";
     5→import type { WorkspaceSection } from "./navigation-meta";
     6→
     7→// ─── Types ──────────────────────────────────────────────────────────────────
     8→
     9→export interface NavigateHeaders {
    10→  label?: string;
    11→  icon?: IconData;
    12→  id?: string;
    13→  sourceNodeId?: string;
    14→  parentNodeId?: string;
    15→  meta?: BreadcrumbMeta;
    16→}
    17→
    18→export interface BreadcrumbMeta {
    19→  workspaceId?: string;
    20→  section?: WorkspaceSection;
    21→  pageSlug?: string;
    22→  agentId?: string;
    23→  executorType?: string;
    24→  webId?: string;
    25→  url?: string;
    26→  blockId?: string;
    27→}
    28→
    29→export interface BreadcrumbStackItem {
    30→  id: string;
    31→  label: string;
    32→  icon?: IconData;
    33→  pattern?: string;
    34→  href?: string;
    35→  sourceNodeId?: string;
    36→  parentNodeId?: string;
    37→  meta?: BreadcrumbMeta;
    38→}
    39→
    40→// ─── Cold Start Builder ─────────────────────────────────────────────────────
    41→
    42→export function buildColdStartBreadcrumb(url: string, headers?: NavigateHeaders): BreadcrumbStackItem[] {
    43→  const match = registry.match(url);
    44→  if (!match) return [];
    45→
    46→  const chain: BreadcrumbStackItem[] = [];
    47→
    48→  // 1. Path prefix ancestors
    49→  for (const ancestorPattern of deriveAncestorsFromPrefix(match.pattern)) {
    50→    const ancestorEntry = registry.getEntry(ancestorPattern)!;
    51→    const ancestorParams = pickMatchingParams(ancestorPattern, match.params);
    52→    chain.push(buildBreadcrumbItem(ancestorEntry, ancestorParams));
    53→  }
    54→
    55→  // 2. Rest param intermediate levels
    56→  const restParam = registry.getRestParam(match.pattern);
    57→  if (restParam && match.params[restParam]?.includes("/")) {
    58→    const segments = match.params[restParam].split("/");
    59→    for (let i = 1; i < segments.length; i++) {
    60→      const prefix = segments.slice(0, i).join("/");
    61→      const lastSegment = segments[i - 1];
    62→      chain.push(buildBreadcrumbItem(
    63→        match.entry,
    64→        { ...match.params, [restParam]: prefix },
    65→        { label: humanize(lastSegment) },
    66→      ));
    67→    }
    68→  }
    69→
    70→  // 3. Current node (headers can override label/icon)
    71→  chain.push(buildBreadcrumbItem(match.entry, match.params, headers));
    72→
    73→  return chain;
    74→}
    75→
    76→// ─── Helpers ────────────────────────────────────────────────────────────────
    77→
    78→export function deriveAncestorsFromPrefix(pattern: string): string[] {
    79→  const segments = pattern.split("/").filter(Boolean);
    80→  const ancestors: string[] = [];
    81→
    82→  for (let i = segments.length - 1; i > 0; i--) {
    83→    const candidate = "/" + segments.slice(0, i).join("/");
    84→    if (registry.hasEntry(candidate)) {
    85→      ancestors.unshift(candidate);
    86→    }
    87→  }
    88→  return ancestors;
    89→}
    90→
    91→export function pickMatchingParams(
    92→  targetPattern: string,
    93→  allParams: Record<string, string>,
    94→): Record<string, string> {
    95→  const paramNames = registry.getParamNames(targetPattern);
    96→  const result: Record<string, string> = {};
    97→  for (const name of paramNames) {
    98→    if (allParams[name] !== undefined) {
    99→      result[name] = allParams[name];
   100→    }
   101→  }
   102→  return result;
   103→}
   104→
   105→export function buildBreadcrumbItem(
   106→  entry: RouteEntry,
   107→  params: Record<string, string>,
   108→  headers?: NavigateHeaders,
   109→): BreadcrumbStackItem {
   110→  const href = registry.build(entry.pattern, params);
   111→  const icon = headers?.icon ?? (typeof entry.icon === "function" ? entry.icon(params) : entry.icon);
   112→  const title = typeof entry.title === "function" ? entry.title(params) : entry.title;
   113→
   114→  return {
   115→    id: headers?.id ?? href,
   116→    label: headers?.label ?? title,
   117→    icon,
   118→    pattern: entry.pattern,
   119→    href,
   120→    sourceNodeId: headers?.sourceNodeId,
   121→    parentNodeId: headers?.parentNodeId,
   122→    meta: headers?.meta,
   123→  };
   124→}
