     1→// apps/desktop/src/navigation/route-registry.ts
     2→import type { RouteEntry } from "./route-compiler";
     3→import { compileRegistry, matchUrlCompiled, buildUrlCompiled, type CompiledRoute, type RouteMatch } from "./route-compiler";
     4→import type { IconData } from "@/components/ui/icon-picker";
     5→
     6→// ─── Route Definitions ──────────────────────────────────────────────────────
     7→
     8→export const ROUTE_ENTRIES: RouteEntry[] = [
     9→  // ─── Top-level ───
    10→  { pattern: "/documents", icon: { type: "lucide", value: "file-text" }, title: "Documents", titleKey: "sidebar.documents", dropdownCategory: "root" },
    11→  { pattern: "/devices/pair", icon: { type: "lucide", value: "smartphone" }, title: "Devices", titleKey: "sidebar.devices", dropdownCategory: "root" },
    12→  { pattern: "/workspace", icon: { type: "lucide", value: "home" }, title: "Workspaces", titleKey: "sidebar.workspaces", isContainer: true, dropdownCategory: "root" },
    13→  { pattern: "/mcp-services", icon: { type: "lucide", value: "server" }, title: "MCP Services", titleKey: "sidebar.mcpServices", isContainer: true, dropdownCategory: "root" },
    14→  { pattern: "/mcp-services/dashboard", icon: { type: "lucide", value: "layout-dashboard" }, title: "Dashboard", titleKey: "sidebar.dashboard", dropdownCategory: "mcp-section" },
    15→  { pattern: "/mcp-services/data-sources", icon: { type: "lucide", value: "database" }, title: "Data Sources", titleKey: "sidebar.dataSources", dropdownCategory: "mcp-section" },
    16→  { pattern: "/mcp-services/search-service", icon: { type: "lucide", value: "search" }, title: "Search Service", titleKey: "sidebar.searchService", dropdownCategory: "mcp-section" },
    17→  { pattern: "/mcp-services/page-debug", icon: { type: "lucide", value: "bug" }, title: "Page Debug", titleKey: "sidebar.pageDebug", dropdownCategory: "mcp-section" },
    18→  { pattern: "/mcp-services/logs", icon: { type: "lucide", value: "scroll-text" }, title: "Logs", titleKey: "sidebar.logs", dropdownCategory: "mcp-section" },
    19→  { pattern: "/publish", icon: { type: "lucide", value: "upload" }, title: "Publish", titleKey: "sidebar.publish", dropdownCategory: "root" },
    20→  { pattern: "/my-packages", icon: { type: "lucide", value: "package" }, title: "My Packages", titleKey: "sidebar.myPackages", dropdownCategory: "root" },
    21→  { pattern: "/analytics", icon: { type: "lucide", value: "chart-column" }, title: "Analytics", titleKey: "sidebar.analytics", dropdownCategory: "root" },
    22→
    23→  // ─── Settings ───
    24→  { pattern: "/settings", icon: { type: "lucide", value: "settings" }, title: "Settings", titleKey: "sidebar.settings", isContainer: true, dropdownCategory: "root" },
    25→  { pattern: "/settings/:section", icon: (p) => getSettingsIcon(p.section), title: (p) => getSettingsTitle(p.section), dropdownCategory: "settings" },
    26→
    27→  // ─── Workspace ───
    28→  { pattern: "/workspace/:workspaceId", icon: { type: "lucide", value: "home" }, title: (p) => p.workspaceId, dropdownCategory: "workspace" },
    29→
    30→  // ─── Workspace Sections ───
    31→  { pattern: "/workspace/:workspaceId/pages", icon: { type: "lucide", value: "layout-grid" }, title: "Pages", titleKey: "workspace.sections.pages", dropdownCategory: "workspace-section" },
    32→  { pattern: "/workspace/:workspaceId/chat", icon: { type: "lucide", value: "message-square" }, title: "Chat", titleKey: "workspace.sections.chat", dropdownCategory: "workspace-section" },
    33→  { pattern: "/workspace/:workspaceId/kanban", icon: { type: "lucide", value: "layout-dashboard" }, title: "Kanban", titleKey: "workspace.sections.kanban", dropdownCategory: "workspace-section" },
    34→  { pattern: "/workspace/:workspaceId/cron", icon: { type: "lucide", value: "clock" }, title: "Scheduled Tasks", titleKey: "workspace.sections.cron", dropdownCategory: "workspace-section" },
    35→  { pattern: "/workspace/:workspaceId/ideas", icon: { type: "lucide", value: "lightbulb" }, title: "Ideas", titleKey: "workspace.sections.ideas", dropdownCategory: "workspace-section" },
    36→  { pattern: "/workspace/:workspaceId/agent", icon: { type: "lucide", value: "bot" }, title: "Agents", titleKey: "workspace.sections.agents", dropdownCategory: "workspace-section" },
    37→  { pattern: "/workspace/:workspaceId/files", icon: { type: "lucide", value: "folder-open" }, title: "Files", titleKey: "workspace.sections.files", dropdownCategory: "workspace-section" },
    38→  { pattern: "/workspace/:workspaceId/github", icon: { type: "lucide", value: "github" }, title: "GitHub", titleKey: "workspace.sections.github", dropdownCategory: "workspace-section" },
    39→  { pattern: "/workspace/:workspaceId/chat-monitor", icon: { type: "lucide", value: "activity" }, title: "Chat Monitor", titleKey: "workspace.sections.chatMonitor", dropdownCategory: "workspace-section" },
    40→
    41→  // ─── Workspace Detail ───
    42→  { pattern: "/workspace/:workspaceId/pages/:pageSlug+", icon: { type: "lucide", value: "file-text" }, title: (p) => humanize(p.pageSlug.split("/").pop()!), dropdownCategory: "page" },
    43→  { pattern: "/workspace/:workspaceId/agent/:agentId", icon: { type: "lucide", value: "bot" }, title: (p) => p.agentId, dropdownCategory: "detail" },
    44→  { pattern: "/workspace/:workspaceId/executor/:executorType", icon: { type: "lucide", value: "terminal" }, title: (p) => p.executorType, dropdownCategory: "detail" },
    45→  { pattern: "/workspace/:workspaceId/web", icon: { type: "lucide", value: "globe" }, title: (p) => p.title ?? "Web", queryParams: ["url", "title", "source_page", "web_id"], dropdownCategory: "detail" },
    46→
    47→  // ─── Global Detail ───
    48→  { pattern: "/agent/:agentId", icon: { type: "lucide", value: "bot" }, title: (p) => p.agentId, queryParams: ["workspace_path"], dropdownCategory: "detail" },
    49→  { pattern: "/executor/:executorType", icon: { type: "lucide", value: "terminal" }, title: (p) => p.executorType, queryParams: ["workspace_path"], dropdownCategory: "detail" },
    50→  { pattern: "/skill/:skillId", icon: { type: "lucide", value: "sparkles" }, title: (p) => p.skillId, queryParams: ["workspace_path", "agent_id"], dropdownCategory: "detail" },
    51→  { pattern: "/mcp-server/:serverName", icon: { type: "lucide", value: "server" }, title: (p) => p.serverName, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
    52→  { pattern: "/subagent/:configId", icon: { type: "lucide", value: "bot" }, title: (p) => p.configId, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
    53→  { pattern: "/prompt/:promptId", icon: { type: "lucide", value: "quote" }, title: (p) => p.promptId, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
    54→  { pattern: "/command/:commandId", icon: { type: "lucide", value: "square-terminal" }, title: (p) => p.commandId, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
    55→
    56→  // ─── Standalone pages (not part of breadcrumb hierarchy, but need registry for normalizeUrl) ───
    57→  { pattern: "/os", icon: { type: "lucide", value: "monitor" }, title: "OS", dropdownCategory: "root" },
    58→  { pattern: "/inspector", icon: { type: "lucide", value: "search" }, title: "Inspector", dropdownCategory: "root" },
    59→  { pattern: "/mcp-marketplace", icon: { type: "lucide", value: "store" }, title: "MCP Marketplace", titleKey: "sidebar.mcpMarketplace", dropdownCategory: "root" },
    60→  { pattern: "/skills-market", icon: { type: "lucide", value: "sparkles" }, title: "Skills Market", titleKey: "sidebar.skillsMarket", dropdownCategory: "root" },
    61→  { pattern: "/chat-monitor", icon: { type: "lucide", value: "activity" }, title: "Chat Monitor", titleKey: "sidebar.chatMonitor", dropdownCategory: "root" },
    62→  { pattern: "/about", icon: { type: "lucide", value: "info" }, title: "About", titleKey: "sidebar.about", dropdownCategory: "root" },
    63→];
    64→
    65→// NOTE: Legacy paths (/workspace/:workspaceId/apps, /workspace/:workspaceId/page,
    66→// /workspace/:workspaceId/agents) are NOT registered and NOT redirected.
    67→// Stored data with these paths is dropped during persist migration.
    68→// App.tsx simply removes these old route definitions.
    69→
    70→// ─── Compiled Registry (singleton) ──────────────────────────────────────────
    71→
    72→const compiled: CompiledRoute[] = compileRegistry(ROUTE_ENTRIES);
    73→const compiledByPattern = new Map(compiled.map((r) => [r.pattern, r]));
    74→
    75→export const registry = {
    76→  match(url: string): RouteMatch | null {
    77→    return matchUrlCompiled(url, compiled);
    78→  },
    79→
    80→  build(pattern: string, params: Record<string, string> = {}): string {
    81→    return buildUrlCompiled(pattern, params, compiled);
    82→  },
    83→
    84→  getEntry(pattern: string): RouteEntry | undefined {
    85→    return compiledByPattern.get(pattern)?.entry;
    86→  },
    87→
    88→  hasEntry(pattern: string): boolean {
    89→    return compiledByPattern.has(pattern);
    90→  },
    91→
    92→  getRestParam(pattern: string): string | null {
    93→    return compiledByPattern.get(pattern)?.restParam ?? null;
    94→  },
    95→
    96→  getParamNames(pattern: string): string[] {
    97→    return compiledByPattern.get(pattern)?.paramNames ?? [];
    98→  },
    99→
   100→  getByCategory(category: string): RouteEntry[] {
   101→    return compiled.filter((r) => r.entry.dropdownCategory === category).map((r) => r.entry);
   102→  },
   103→
   104→  getIcon(pattern: string, params: Record<string, string> = {}): IconData | undefined {
   105→    const entry = compiledByPattern.get(pattern)?.entry;
   106→    if (!entry) return undefined;
   107→    return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   108→  },
   109→
   110→  normalizeUrl(url: string): string {
   111→    const match = this.match(url);
   112→    if (!match) {
   113→      const { pathname } = new URL(url, "http://localhost");
   114→      return pathname;
   115→    }
   116→    return this.build(match.pattern, match.params);
   117→  },
   118→};
   119→
   120→// ─── Helpers ────────────────────────────────────────────────────────────────
   121→
   122→export function humanize(slug: string): string {
   123→  return slug.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
   124→}
   125→
   126→function getSettingsIcon(_section: string): IconData {
   127→  return { type: "lucide", value: "settings" };
   128→}
   129→
   130→function getSettingsTitle(section: string): string {
   131→  return humanize(section);
   132→}
