   526→    const entry = compiledByPattern.get(pattern)?.entry;
   527→    if (!entry) return undefined;
   528→    return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   529→  },
   530→
   531→  normalizeUrl(url: string): string {
   532→    const match = this.match(url);
   533→    if (!match) {
