   214→export function getTabCurrentState(tab: PageTab): TabNavigationState | null {
   215→  return tab.navigationHistory[tab.historyIndex] ?? null;
   216→}
   217→
   218→export function getTabCurrentLeaf(tab: PageTab): BreadcrumbStackItem | null {
   219→  const current = getTabCurrentState(tab);
   220→  return current?.breadcrumbStack[current.breadcrumbStack.length - 1] ?? null;
   221→}
   222→
   223→export function getTabUrl(tab: PageTab): string | null {
   224→  const current = getTabCurrentState(tab);
   225→  return current?.url ?? null;
   226→}
