   228→export function getTabViewModel(tab: PageTab): TabViewModel {
   229→  const currentState = getTabCurrentState(tab);
   230→  const leaf = getTabCurrentLeaf(tab);
   231→  const url = getTabUrl(tab);
   232→
   233→  return {
   234→    ...tab,
   235→    currentState,
   236→    currentUrl: url,
   237→    label: leaf?.label ?? url ?? "Untitled",
   238→    icon: leaf?.icon,
   239→    descriptorId: leaf?.pattern,
   240→    meta: leaf?.meta,
   241→    url,
   242→  };
   243→}
   244→
   245→function findHistoryEntryByUrlInHistory(
   246→  navigationHistory: TabNavigationState[],
   247→  historyIndex: number,
   248→  url: string
   249→): number {
   250→  for (let index = historyIndex - 1; index >= 0; index -= 1) {
   251→    if (navigationHistory[index].url === url) {
   252→      return index;
   253→    }
   254→  }
   255→  return -1;
   256→}
