    25→  return useMemo(() => rawTabs.map(getTabViewModel), [rawTabs]);
    26→}
    27→
    28→// ─── Hook 2: useActiveTabState ──────────────────────────────────────────────
    29→// Returns reactive state about the active tab. Re-renders when active tab changes.
    30→
    31→export interface ActiveTabState {
    32→  activeTabId: string | null;
    33→  activeTab: TabViewModel | null;
    34→  canGoBack: boolean;
    35→  canGoForward: boolean;
    36→  currentUrl: string | null;
    37→  currentNavigationState: TabNavigationState | null;
    38→}
    39→
    40→export function useActiveTabState(): ActiveTabState {
    41→  const activeTabId = useTabStore((state) => state.activeTabId);
    42→  const activeTabRaw = useTabStore((state) =>
    43→    state.tabs.find((tab) => tab.id === state.activeTabId) ?? null
    44→  );
    45→  const canGoBackFn = useTabStore((state) => state.canGoBack);
    46→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
    47→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
    48→  const getCurrentNavigationState = useTabStore(
    49→    (state) => state.getCurrentNavigationState
    50→  );
    51→
    52→  const activeTab = useMemo(
    53→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    54→    [activeTabRaw]
    55→  );
    56→
    57→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    58→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    59→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    60→  const currentNavigationState = activeTabId
    61→    ? getCurrentNavigationState(activeTabId)
    62→    : null;
    63→
    64→  return useMemo(
    65→    () => ({
    66→      activeTabId,
    67→      activeTab,
    68→      canGoBack,
    69→      canGoForward,
    70→      currentUrl,
    71→      currentNavigationState,
    72→    }),
    73→    [activeTabId, activeTab, canGoBack, canGoForward, currentUrl, currentNavigationState]
    74→  );
    75→}
    76→
    77→// ─── Hook 3: useTabActions ──────────────────────────────────────────────────
    78→// Returns stable action functions for tab operations. These reference Zustand
    79→// store actions + resolve navigation logic. Actions that depend on activeTabId
    80→// will have their identity change when activeTabId changes.
    81→
    82→export interface TabActions {
    83→  openLocation: (
    84→    location: DesktopLocation,
    85→    options?: { breadcrumbStack?: BreadcrumbStackItem[]; openInNewTab?: boolean }
    86→  ) => string;
    87→  replaceLocation: (
    88→    location: DesktopLocation,
    89→    patch?: Partial<TabNavigationState>
    90→  ) => string | undefined;
    91→  pushLocation: (
    92→    location: DesktopLocation,
    93→    patch?: Partial<TabNavigationState>
    94→  ) => string | undefined;
    95→  pushPage: (
    96→    item: BreadcrumbStackItem,
    97→    nextLocation: DesktopLocation,
    98→    options?: PushPageOptions
    99→  ) => string | undefined;
   100→  popTo: (index: number) => void;
   101→  resetStack: (next: TabNavigationState) => string | undefined;
   102→  navigateTo: (
   103→    url: string,
   104→    input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }
   105→  ) => string | undefined;
   106→  openPageTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   107→  openPageInNewTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   108→  openWorkspaceView: (workspaceId: string, viewPath: string, viewName: string, icon: IconData) => string;
   109→  openGlobalView: (path: string, name: string, icon: IconData) => string;
   110→  openWebUrl: (url: string, title?: string, workspaceId?: string) => string;
   111→  openChatTab: (chatId: string, chatName: string, workspaceId: string) => string;
   112→  switchToTab: (tabId: string) => string | null;
   113→  closeTab: (tabId: string) => void;
   114→  detachTabToNewWindow: (tabId: string) => Promise<boolean>;
   115→  getTabLink: (tabId: string) => string | null;
   116→}
   117→
   118→export function useTabActions(): TabActions {
   119→  const { getWorkspace } = useLocalWorkspaces();
   120→  const activeTabId = useTabStore((state) => state.activeTabId);
   121→  const rawTabs = useTabStore((state) => state.tabs);
   122→
   123→  const openTab = useTabStore((state) => state.openTab);
   124→  const closeTabStore = useTabStore((state) => state.closeTab);
   125→  const setActiveTab = useTabStore((state) => state.setActiveTab);
   126→  const replaceLocationStore = useTabStore((state) => state.replaceLocation);
   127→  const pushLocationStore = useTabStore((state) => state.pushLocation);
   128→  const pushPageStore = useTabStore((state) => state.pushPage);
   129→  const popToStore = useTabStore((state) => state.popTo);
   130→  const resetStackStore = useTabStore((state) => state.resetStack);
   131→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
   132→  const getCurrentNavigationState = useTabStore(
   133→    (state) => state.getCurrentNavigationState
   134→  );
   135→
   136→  const resolveNavigation = useCallback(
   137→    (
   138→      location: DesktopLocation,
   139→      input?: {
   140→        breadcrumbStack?: BreadcrumbStackItem[];
   141→        title?: string;
   142→        icon?: IconData;
   143→        workspaceId?: string;
   144→      }
   145→    ) => {
   146→      if (input?.breadcrumbStack?.length) {
   147→        return { breadcrumbStack: input.breadcrumbStack };
   148→      }
   149→
   150→      const url = locationToUrl(location);
   151→      const stack = buildColdStartBreadcrumb(url, {
   152→        label: input?.title,
   153→        icon: input?.icon,
   154→      });
   155→
   156→      // Cast: breadcrumb-builder's BreadcrumbStackItem is structurally compatible
   157→      // with navigation-meta's version at runtime
   158→      return { breadcrumbStack: stack as unknown as BreadcrumbStackItem[] };
   159→    },
   160→    []
   161→  );
   162→
   163→  const openLocation = useCallback(
   164→    (
   165→      location: DesktopLocation,
   166→      options?: {
   167→        breadcrumbStack?: BreadcrumbStackItem[];
   168→        openInNewTab?: boolean;
   169→      }
   170→    ) => {
   171→      const resolvedNavigation = resolveNavigation(location, {
   172→        breadcrumbStack: options?.breadcrumbStack,
   173→      });
   174→      const navigationState: TabNavigationState = {
   175→        location,
   176→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
   177→      };
   178→
   179→      if (options?.openInNewTab || !activeTabId) {
   180→        return openTab({
   181→          navigationState,
   182→          pinned: false,
   183→        });
   184→      }
   185→
   186→      replaceLocationStore(activeTabId, navigationState);
   187→      return activeTabId;
   188→    },
   189→    [activeTabId, openTab, replaceLocationStore, resolveNavigation]
   190→  );
   191→
   192→  const replaceLocation = useCallback(
   193→    (
   194→      location: DesktopLocation,
   195→      patch?: Partial<TabNavigationState>
   196→    ) => {
   197→      if (!activeTabId) {
   198→        return openLocation(location, {
   199→          breadcrumbStack: patch?.breadcrumbStack,
   200→          openInNewTab: true,
   201→        });
   202→      }
   203→
   204→      const resolvedNavigation = resolveNavigation(location, {
   205→        breadcrumbStack: patch?.breadcrumbStack,
   206→      });
   207→      replaceLocationStore(activeTabId, {
   208→        location,
   209→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
   210→        activeIndexPath: patch?.activeIndexPath,
   211→        activeNodeId: patch?.activeNodeId,
   212→      });
   213→      return activeTabId;
   214→    },
   215→    [activeTabId, openLocation, replaceLocationStore, resolveNavigation]
   216→  );
   217→
   218→  const pushLocation = useCallback(
   219→    (
   220→      location: DesktopLocation,
   221→      patch?: Partial<TabNavigationState>
   222→    ) => {
   223→      if (!activeTabId) {
   224→        return openLocation(location, {
   225→          breadcrumbStack: patch?.breadcrumbStack,
   226→          openInNewTab: true,
   227→        });
   228→      }
   229→
   230→      const resolvedNavigation = resolveNavigation(location, {
   231→        breadcrumbStack: patch?.breadcrumbStack,
   232→      });
   233→      pushLocationStore(activeTabId, {
   234→        location,
   235→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
   236→        activeIndexPath: patch?.activeIndexPath,
   237→        activeNodeId: patch?.activeNodeId,
   238→      });
   239→      return activeTabId;
   240→    },
   241→    [activeTabId, openLocation, pushLocationStore, resolveNavigation]
   242→  );
   243→
   244→  const pushPage = useCallback(
   245→    (
   246→      item: BreadcrumbStackItem,
   247→      nextLocation: DesktopLocation,
   248→      options?: PushPageOptions
   249→    ) => {
   250→      if (!activeTabId) {
   251→        const resolvedNavigation = resolveNavigation(nextLocation, {
   252→          title: item.label,
   253→          icon: item.icon,
   254→        });
   255→        return openLocation(nextLocation, {
   256→          breadcrumbStack: [...resolvedNavigation.breadcrumbStack, item],
   257→          openInNewTab: true,
   258→        });
   259→      }
   260→
   261→      pushPageStore(activeTabId, item, nextLocation, options);
   262→      return activeTabId;
   263→    },
   264→    [activeTabId, openLocation, pushPageStore, resolveNavigation]
   265→  );
   266→
   267→  const popTo = useCallback(
   268→    (index: number) => {
   269→      if (!activeTabId) return;
   270→      popToStore(activeTabId, index);
   271→    },
   272→    [activeTabId, popToStore]
   273→  );
   274→
   275→  const resetStack = useCallback(
   276→    (next: TabNavigationState) => {
   277→      if (!activeTabId) {
   278→        return openLocation(next.location, {
   279→          breadcrumbStack: next.breadcrumbStack,
   280→          openInNewTab: true,
   281→        });
   282→      }
   283→
   284→      resetStackStore(activeTabId, next);
   285→      return activeTabId;
   286→    },
   287→    [activeTabId, openLocation, resetStackStore]
   288→  );
   289→
   290→  const navigateTo = useCallback(
   291→    (url: string, input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }) => {
   292→      const isExternal = url.startsWith("http://") || url.startsWith("https://");
   293→      if (isExternal) {
   294→        const workspaceId = input.meta?.workspaceId ?? "global";
   295→        return openLocation(
   296→          {
   297→            kind: "workspace-web",
   298→            workspaceId,
   299→            url,
   300→            title: input.label,
   301→          },
   302→          { openInNewTab: false }
   303→        );
   304→      }
   305→
   306→      if (activeTabId) {
   307→        const location = buildLocationFromLegacyUrl(url);
   308→        const resolvedNavigation = resolveNavigation(location, {
   309→          title: input.label,
   310→          icon: input.icon,
   311→          workspaceId: input.meta?.workspaceId,
   312→        });
   313→        replaceLocationStore(activeTabId, {
   314→          location,
   315→          breadcrumbStack: resolvedNavigation.breadcrumbStack,
   316→        });
   317→        return activeTabId;
   318→      }
   319→
   320→      const location = buildLocationFromLegacyUrl(url);
   321→      const resolvedNavigation = resolveNavigation(location, {
   322→        title: input.label,
   323→        icon: input.icon,
   324→        workspaceId: input.meta?.workspaceId,
   325→      });
   326→      return openTab({
   327→        pinned: false,
   328→        navigationState: {
   329→          location,
   330→          breadcrumbStack: resolvedNavigation.breadcrumbStack,
   331→        },
   332→      });
   333→    },
   334→    [activeTabId, openLocation, openTab, replaceLocationStore, resolveNavigation]
   335→  );
   336→
   337→  const openPageTab = useCallback(
   338→    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) =>
   339→      openLocation(
   340→        { kind: "workspace-page", workspaceId, pageSlug: page.slug },
   341→        { breadcrumbStack }
   342→      ),
   343→    [openLocation]
   344→  );
   345→
   346→  const openPageInNewTab = useCallback(
   347→    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) =>
   348→      openLocation(
   349→        { kind: "workspace-page", workspaceId, pageSlug: page.slug },
   350→        { openInNewTab: true, breadcrumbStack }
   351→      ),
   352→    [openLocation]
   353→  );
   354→
   355→  const openWorkspaceView = useCallback(
   356→    (workspaceId: string, viewPath: string, _viewName: string, _icon: IconData) => {
   357→      if (!viewPath) {
   358→        return openLocation({ kind: "workspace-home", workspaceId });
   359→      }
   360→      return openLocation({
   361→        kind: "workspace-section",
   362→        workspaceId,
   363→        section: normalizeWorkspaceSection(viewPath),
   364→      });
   365→    },
   366→    [openLocation]
   367→  );
   368→
   369→  const openGlobalView = useCallback(
   370→    (path: string, _name: string, _icon: IconData) => {
   371→      const location = buildLocationFromLegacyUrl(path);
   372→      return openLocation(location);
   373→    },
   374→    [openLocation]
   375→  );
   376→
   377→  const openWebUrl = useCallback(
   378→    (url: string, title?: string, workspaceId?: string) => {
   379→      // Derive workspaceId from current tab URL via registry match
   380→      const currentTabUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
   381→      const routeMatch = currentTabUrl ? registry.match(currentTabUrl) : null;
   382→      const wsId =
   383→        workspaceId ??
   384→        routeMatch?.params.workspaceId ??
   385→        "global";
   386→      return openLocation({
   387→        kind: "workspace-web",
   388→        workspaceId: wsId,
   389→        title: title ?? safeHostname(url),
   390→        url,
   391→      });
   392→    },
   393→    [activeTabId, getCurrentUrl, openLocation]
   394→  );
   395→
   396→  const openChatTab = useCallback(
   397→    (_chatId: string, _chatName: string, workspaceId: string) =>
   398→      openLocation({
   399→        kind: "workspace-section",
   400→        workspaceId,
   401→        section: "chat",
   402→      }),
   403→    [openLocation]
   404→  );
   405→
   406→  const switchToTab = useCallback(
   407→    (tabId: string) => {
   408→      setActiveTab(tabId);
   409→      return getCurrentUrl(tabId);
   410→    },
   411→    [getCurrentUrl, setActiveTab]
   412→  );
   413→
   414→  const closeTab = useCallback(
   415→    (tabId: string) => {
   416→      closeTabStore(tabId);
   417→    },
   418→    [closeTabStore]
   419→  );
   420→
   421→  const getTabLink = useCallback(
   422→    (tabId: string) => {
   423→      const state = getCurrentNavigationState(tabId);
   424→      return state ? locationToUrl(state.location) : null;
   425→    },
   426→    [getCurrentNavigationState]
   427→  );
   428→
   429→  const detachTabToNewWindow = useCallback(
   430→    async (tabId: string) => {
   431→      const tab = rawTabs.find((item) => item.id === tabId);
   432→      const state = getCurrentNavigationState(tabId);
   433→      const tabView = tab ? getTabViewModel(tab) : null;
   434→
   435→      if (!tab || !state || !("workspaceId" in state.location)) {
   436→        return false;
   437→      }
   438→
   439→      if (state.location.kind === "workspace-page") {
   440→        const workspace = getWorkspace(state.location.workspaceId);
   441→        if (!workspace?.path) {
   442→          return false;
   443→        }
   444→
   445→        await invoke("open_workspace_page_preview_window", {
   446→          workspaceId: state.location.workspaceId,
   447→          workspacePath: workspace.path,
   448→          slug: state.location.pageSlug,
   449→          title: tabView?.label ?? state.location.pageSlug,
   450→          view: tab.viewMode ?? "page",
   451→        });
   452→        closeTabStore(tabId);
   453→        return true;
   454→      }
   455→
   456→      const routePath = locationToUrl(state.location);
   457→      await invoke("open_workspace_in_new_window", {
   458→        workspaceId: state.location.workspaceId,
   459→        routePath,
   460→        title: tabView?.label ?? routePath,
   461→      });
   462→      closeTabStore(tabId);
   463→      return true;
   464→    },
   465→    [closeTabStore, getCurrentNavigationState, getWorkspace, rawTabs]
   466→  );
   467→
   468→  return useMemo(
   469→    () => ({
   470→      openLocation,
   471→      replaceLocation,
   472→      pushLocation,
   473→      pushPage,
   474→      popTo,
   475→      resetStack,
   476→      navigateTo,
   477→      openPageTab,
   478→      openPageInNewTab,
   479→      openWorkspaceView,
   480→      openGlobalView,
   481→      openWebUrl,
   482→      openChatTab,
   483→      switchToTab,
   484→      closeTab,
   485→      detachTabToNewWindow,
   486→      getTabLink,
   487→    }),
   488→    [
   489→      openLocation,
   490→      replaceLocation,
   491→      pushLocation,
   492→      pushPage,
   493→      popTo,
   494→      resetStack,
   495→      navigateTo,
   496→      openPageTab,
   497→      openPageInNewTab,
   498→      openWorkspaceView,
   499→      openGlobalView,
   500→      openWebUrl,
   501→      openChatTab,
   502→      switchToTab,
   503→      closeTab,
   504→      detachTabToNewWindow,
   505→      getTabLink,
   506→    ]
   507→  );
   508→}
   509→
   510→// ─── Hook 4: useTabNavigation ───────────────────────────────────────────────
   511→// Returns navigation actions bound to the active tab (history back/forward/jump).
   512→
   513→export interface TabNavigationActions {
   514→  goBackInTab: () => void;
   515→  goForwardInTab: () => void;
   516→  jumpToHistory: (historyIndex: number) => void;
   517→  navigateInTab: (url: string) => void;
   518→}
   519→
   520→export function useTabNavigation(): TabNavigationActions {
   521→  const activeTabId = useTabStore((state) => state.activeTabId);
   522→  const navigate = useTabStore((state) => state.navigate);
   523→  const goBack = useTabStore((state) => state.goBack);
   524→  const goForward = useTabStore((state) => state.goForward);
   525→  const canGoBackFn = useTabStore((state) => state.canGoBack);
   526→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
   527→  const jumpToHistoryStore = useTabStore((state) => state.jumpToHistory);
   528→
   529→  const goBackInTab = useCallback(() => {
   530→    if (activeTabId && canGoBackFn(activeTabId)) {
   531→      goBack(activeTabId);
   532→    }
   533→  }, [activeTabId, canGoBackFn, goBack]);
   534→
   535→  const goForwardInTab = useCallback(() => {
   536→    if (activeTabId && canGoForwardFn(activeTabId)) {
   537→      goForward(activeTabId);
   538→    }
   539→  }, [activeTabId, canGoForwardFn, goForward]);
   540→
   541→  const jumpToHistory = useCallback(
   542→    (historyIndex: number) => {
   543→      if (!activeTabId) return;
   544→      jumpToHistoryStore(activeTabId, historyIndex);
   545→    },
   546→    [activeTabId, jumpToHistoryStore]
   547→  );
   548→
   549→  const navigateInTab = useCallback(
   550→    (url: string) => {
   551→      if (!activeTabId) return;
   552→      navigate(activeTabId, url);
   553→    },
   554→    [activeTabId, navigate]
   555→  );
   556→
   557→  return useMemo(
   558→    () => ({ goBackInTab, goForwardInTab, jumpToHistory, navigateInTab }),
   559→    [goBackInTab, goForwardInTab, jumpToHistory, navigateInTab]
   560→  );
   561→}
   562→
   563→// ─── Composed hook: usePageTabs (backward-compatible) ───────────────────────
   564→// Composes the 4 granular hooks. Existing consumers can continue using this
   565→// without changes, but new code should prefer the granular hooks.
   566→
   567→export function usePageTabs() {
   568→  const tabs = useTabList();
   569→  const activeState = useActiveTabState();
   570→  const actions = useTabActions();
   571→  const navigation = useTabNavigation();
   572→
   573→  return useMemo(
   574→    () => ({
   575→      tabs,
   576→      ...activeState,
   577→      ...actions,
   578→      ...navigation,
   579→    }),
   580→    [tabs, activeState, actions, navigation]
   581→  );
   582→}
   583→
   584→// ─── Utilities ──────────────────────────────────────────────────────────────
   585→
   586→function safeHostname(url: string): string {
   587→  try {
   588→    return new URL(url).hostname;
   589→  } catch {
   590→    return url;
   591→  }
   592→}
   593→
   594→function buildLocationFromLegacyUrl(url: string): DesktopLocation {
   595→  const parsed = urlToLocation(url);
   596→  if (parsed) {
   597→    return parsed;
   598→  }
   599→
   600→  if (url === "/documents") {
   601→    return { kind: "documents" };
   602→  }
   603→  if (url === "/devices/pair") {
   604→    return { kind: "device-pair" };
   605→  }
   606→  if (url.startsWith("/settings")) {
   607→    const section = url.split("/")[2];
   608→    return { kind: "settings", section: normalizeSettingsSection(section) };
   609→  }
   610→
   611→  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
   612→    return { kind: "global-route", path: url };
   613→  }
   614→
   615→  if (url.startsWith("/workspace/page")) {
   616→    const parsed = new URL(url, "http://desktop.local");
   617→    const workspaceId = parsed.searchParams.get("workspace_id");
   618→    const pagePath = parsed.searchParams.get("page_path");
   619→    return {
   620→      kind: "workspace-page",
   621→      workspaceId: workspaceId ?? "global",
   622→      pageSlug:
   623→        pagePath?.replace(/^pages\//, "").replace(/\/SKILL\.md$/, "") ?? "page",
   624→    };
   625→  }
   626→
   627→  if (url.startsWith("/workspace/")) {
   628→    const parsed = new URL(url, "http://desktop.local");
   629→    const parts = parsed.pathname.split("/").filter(Boolean);
   630→    const workspaceId = parts[1];
   631→    if (!workspaceId) {
   632→      return { kind: "documents" };
   633→    }
   634→
   635→    if (parts.length === 2) {
   636→      return { kind: "workspace-home", workspaceId };
   637→    }
   638→
   639→    if (parts[2] === "apps" && !parts[3]) {
   640→      return { kind: "workspace-apps", workspaceId };
   641→    }
   642→
   643→    if (parts[2] === "page" && parts[3]) {
   644→      return {
   645→        kind: "workspace-page",
   646→        workspaceId,
   647→        pageSlug: parts
   648→          .slice(3)
   649→          .map((part) => decodeURIComponent(part))
   650→          .join("/"),
   651→      };
   652→    }
   653→
   654→    if (parts[2] === "agent" && parts[3]) {
   655→      return {
   656→        kind: "workspace-agent-detail",
   657→        workspaceId,
   658→        agentId: decodeURIComponent(parts[3]),
   659→      };
   660→    }
   661→
   662→    if (parts[2] === "executor" && parts[3]) {
