   681→    return {
   682→      kind: "workspace-section",
   683→      workspaceId,
   684→      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
   685→    };
   686→  }
   687→
   688→  return { kind: "global-route", path: url };
